const results = {};
for (const [name, fn] of Object.entries({
  processEnv: () => process.env,
  filesystemRoot: () => require('fs').readdirSync('/'),
  bunGlobal: () => globalThis.Bun,
  fetchExample: () => fetch('https://example.com'),
})) {
  try {
    const value = await fn();
    results[name] = value === undefined ? { status: 'success', value: 'undefined' } : { status: 'success', valueType: typeof value };
  } catch (error) {
    results[name] = { status: 'error', name: error?.name, message: error?.message };
  }
}
return results;

